import { MakeLogicType, actions, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import posthog from 'lib/posthog-typed'
import { getCurrentTeamId } from 'lib/utils/getAppContext'

import { dashboardsActivitySummaryRetrieve } from './generated/api'
import type { DashboardActivitySummaryApi } from './generated/api.schemas'

export interface DashboardActivitySummaryLogicProps {
    dashboardId: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dashboardActivitySummaryLogicValues {
    activitySummary: DashboardActivitySummaryApi | null
    activitySummaryFailed: boolean
    activitySummaryLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dashboardActivitySummaryLogicActions {
    loadActivitySummary: () => any
    loadActivitySummaryFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadActivitySummarySuccess: (
        activitySummary: DashboardActivitySummaryApi,
        payload?: any
    ) => {
        activitySummary: DashboardActivitySummaryApi
        payload?: any
    }
    openActivitySummary: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dashboardActivitySummaryLogicMeta {
    key: number
}

export type dashboardActivitySummaryLogicType = MakeLogicType<
    dashboardActivitySummaryLogicValues,
    dashboardActivitySummaryLogicActions,
    DashboardActivitySummaryLogicProps,
    dashboardActivitySummaryLogicMeta
>

export const dashboardActivitySummaryLogic = kea<dashboardActivitySummaryLogicType>([
    path((key) => ['scenes', 'dashboard', 'dashboardActivitySummaryLogic', key]),
    props({} as DashboardActivitySummaryLogicProps),
    key((props) => props.dashboardId),
    actions({
        openActivitySummary: true,
    }),
    loaders(({ props }) => ({
        activitySummary: [
            null as DashboardActivitySummaryApi | null,
            {
                loadActivitySummary: async () => {
                    posthog.capture('dashboard activity summary viewed', { dashboard_id: props.dashboardId })
                    return await dashboardsActivitySummaryRetrieve(String(getCurrentTeamId()), props.dashboardId)
                },
            },
        ],
    })),
    reducers({
        activitySummaryFailed: [
            false,
            {
                loadActivitySummary: () => false,
                loadActivitySummaryFailure: () => true,
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        openActivitySummary: () => {
            if (!values.activitySummary && !values.activitySummaryLoading && !values.activitySummaryFailed) {
                actions.loadActivitySummary()
            }
        },
    })),
])
